/// Returns 1.0 if `i == j`, otherwise returns 0.0.
#[requires(true)]
#[ensures(|ret: f64| ret == if i == j { 1.0 } else { 0.0 })]
fn diag_val(i: usize, j: usize) -> f64 {
    if i == j {
        1.0
    } else {
        0.0
    }
}

/// Constructs an `n x n` identity matrix of `f64`
///
/// # Arguments
///
/// * `n` – the dimension of the square identity matrix
///
/// # Returns
///
/// A vector of `n` rows, each of which is a vector of `n` `f64` values,
/// where the diagonal entries are 1.0 and all off-diagonal entries are 0.0.
#[requires(true)]
#[ensures(|res: Vec<Vec<f64>>|
    // outer dimension is n
    res.len() == n
    // each row has length n, and entries satisfy the identity property
    && forall(|i: usize| (i < n) ==> (
         res[i].len() == n
         && forall(|j: usize| (j < n) ==> (res[i][j] == if i == j { 1.0 } else { 0.0 }))
    ))
)]
fn identity(n: usize) -> Vec<Vec<f64>> {
    // Pre-allocate the outer vector with capacity `n`
    let mut mat: Vec<Vec<f64>> = Vec::with_capacity(n);

    // we can annotate a for‐loop with invariants and a decreases clause:
    #[invariant(
        // iteration index i is in range
        0 <= i && i <= n
    )]
    #[invariant(
        // we have already pushed exactly i rows
        mat.len() == i
    )]
    #[invariant(
        // and each of those rows is length n and satisfies the diag property
        forall(|k: usize| (k < i) ==> (
            mat[k].len() == n
            && forall(|j: usize| (j < n) ==> (
                mat[k][j] == if k == j { 1.0 } else { 0.0 }
            ))
        ))
    )]
    #[decreases(n - i)]
    for i in 0..n {
        // For each row, pre-allocate a vector of length `n`
        let mut row: Vec<f64> = Vec::with_capacity(n);

        // Inner loop to build row
        #[invariant(
            // inner index j is in range
            0 <= j && j <= n
        )]
        #[invariant(
            // we've pushed exactly j entries so far
            row.len() == j
        )]
        #[invariant(
            // those j entries satisfy the diag property at row i
            forall(|k: usize| (k < j) ==> (row[k] == if i == k { 1.0 } else { 0.0 }))
        )]
        #[decreases(n - j)]
        for j in 0..n {
            row.push(diag_val(i, j));
        }

        mat.push(row);
    }

    mat
}

